create table if not exists distributors(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),name text not null,code text not null,territory text,credit_limit numeric(14,2) default 0,created_at timestamptz default now(),unique(tenant_id,code));
create table if not exists wholesalers(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),name text not null,code text not null,territory text,created_at timestamptz default now(),unique(tenant_id,code));
create table if not exists sales_executives(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),name text not null,phone text,territory text,distributor_id uuid references distributors(id),target numeric(14,2) default 0,active boolean default true,created_at timestamptz default now());
create table if not exists schemes(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),name text not null,scheme_type text not null,rule jsonb not null default '{}',active boolean default true,created_at timestamptz default now());
